#!/usr/bin/env bash
set -euo pipefail

# Smoke check after a rebuild: prints each tool's version and fails if one is
# missing. Generated by devcontainer-kit; add project-specific checks below.

show_version() {
  printf '==> %-28s' "$1"
  shift
  "$@" 2>&1 | sed -n '1p'
}

show_version 'go' go version
show_version 'ruby' ruby --version
show_version 'gem' gem --version
show_version 'bundle' bundle --version
show_version 'rails' rails --version
show_version 'sqlite3' sqlite3 --version
show_version 'node' node --version
show_version 'npm' npm --version
show_version 'git' git --version
show_version 'jq' jq --version

printf '\nAll dependency checks passed.\n'
